import java.io.*;import java.nio.file.*;import java.util.*;import java.util.zip.*;import org.jf.dexlib2.*;import org.jf.dexlib2.dexbacked.*;import org.jf.dexlib2.iface.*;import org.jf.dexlib2.iface.instruction.*;import org.jf.dexlib2.iface.reference.*;import org.jf.dexlib2.iface.value.*;
class NativeDexGraph {
 static void type(Set<String>s,String t){if(t==null)return;while(t.startsWith("["))t=t.substring(1);if(t.startsWith("L"))s.add(t);}
 static void reference(Set<String>s,Reference r){if(r instanceof TypeReference)type(s,((TypeReference)r).getType());else if(r instanceof MethodReference){MethodReference m=(MethodReference)r;type(s,m.getDefiningClass());type(s,m.getReturnType());for(CharSequence p:m.getParameterTypes())type(s,p.toString());}else if(r instanceof FieldReference){FieldReference f=(FieldReference)r;type(s,f.getDefiningClass());type(s,f.getType());}else if(r instanceof StringReference){String x=((StringReference)r).getString();if(x.matches("[A-Za-z_$][A-Za-z0-9_$.]+"))type(s,"L"+x.replace('.','/')+";");}else if(r instanceof MethodProtoReference){MethodProtoReference m=(MethodProtoReference)r;type(s,m.getReturnType());for(CharSequence p:m.getParameterTypes())type(s,p.toString());}}
 static void value(Set<String>s,EncodedValue v){if(v==null)return;if(v instanceof TypeEncodedValue)type(s,((TypeEncodedValue)v).getValue());else if(v instanceof FieldEncodedValue)reference(s,((FieldEncodedValue)v).getValue());else if(v instanceof MethodEncodedValue)reference(s,((MethodEncodedValue)v).getValue());else if(v instanceof EnumEncodedValue)reference(s,((EnumEncodedValue)v).getValue());else if(v instanceof ArrayEncodedValue)for(EncodedValue x:((ArrayEncodedValue)v).getValue())value(s,x);else if(v instanceof AnnotationEncodedValue){AnnotationEncodedValue x=(AnnotationEncodedValue)v;type(s,x.getType());for(AnnotationElement e:x.getElements())value(s,e.getValue());}}
 static void annotations(Set<String>s,Set<? extends Annotation>a){for(Annotation x:a){type(s,x.getType());for(AnnotationElement e:x.getElements())value(s,e.getValue());}}
 public static void main(String[]a)throws Exception{
  try(ZipFile zip=new ZipFile(a[0]);PrintWriter out=new PrintWriter(a[1])){List<? extends ZipEntry> entries=Collections.list(zip.entries());entries.sort(Comparator.comparing(ZipEntry::getName));for(ZipEntry e:entries){String n=e.getName();if(!n.endsWith(".dex")||n.contains("/"))continue;byte[]data=zip.getInputStream(e).readAllBytes();DexBackedDexFile d=new DexBackedDexFile(Opcodes.forApi(30),data);int count=0;for(ClassDef c:d.getClasses()){Set<String>s=new TreeSet<>();type(s,c.getSuperclass());for(String t:c.getInterfaces())type(s,t);annotations(s,c.getAnnotations());for(Field f:c.getFields()){type(s,f.getType());annotations(s,f.getAnnotations());value(s,f.getInitialValue());}for(Method m:c.getMethods()){type(s,m.getReturnType());for(MethodParameter p:m.getParameters()){type(s,p.getType());annotations(s,p.getAnnotations());}annotations(s,m.getAnnotations());MethodImplementation impl=m.getImplementation();if(impl==null)continue;for(Instruction i:impl.getInstructions()){if(i instanceof ReferenceInstruction)reference(s,((ReferenceInstruction)i).getReference());if(i instanceof DualReferenceInstruction)reference(s,((DualReferenceInstruction)i).getReference2());}for(TryBlock<? extends ExceptionHandler>t:impl.getTryBlocks())for(ExceptionHandler h:t.getExceptionHandlers())type(s,h.getExceptionType());}s.remove(c.getType());out.println(c.getType()+"\t"+n+"\t"+String.join(",",s));count++;}out.flush();System.out.println(n+" "+count);}}
 }
}
